INSERT INTO work_queue (id,task_type,payload,status,created_at) SELECT 'pending-backfill-guard','metadata','{}','guard_failed',unixepoch() WHERE NOT ((SELECT COUNT(*) FROM c JOIN song_masters sm ON sm.id=c.master_id AND sm.album_id='pending-uploads' AND sm.title IS c.title_snapshot AND sm.disc IS c.disc_snapshot AND sm.track IS c.track_snapshot JOIN song_instances si ON si.id=c.instance_id AND si.master_id=sm.id AND si.source_id='r2-local' AND si.source_type='original' AND si.missing=0 AND si.tag_scanned=1 AND lower(si.suffix)='wav' AND si.storage_object_id=c.object_id JOIN storage_entries se ON se.id=c.entry_id AND se.instance_id=si.id AND se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-75d346df2f574adeb9b44b73a2dc9fd4' AND se.object_id=si.storage_object_id JOIN storage_objects so ON so.id=c.object_id WHERE (SELECT COUNT(*) FROM storage_entries f WHERE f.instance_id=si.id AND f.kind='file')=1)=8 AND NOT EXISTS (SELECT 1 FROM albums WHERE id='al-44bf6641ecfaf08f307a0587cd16c784') AND NOT EXISTS (SELECT 1 FROM song_masters WHERE id IN ('sm-upload-08c5fd9b-a07','sm-upload-0f6e0515-62c','sm-upload-5979a6ff-f6c','sm-upload-746012d3-887','sm-upload-75a8634a-1b1','sm-upload-8aa9653f-bb6','sm-upload-9ac28768-466','sm-upload-b4e17f3c-27c') GROUP BY lower(trim(title)) HAVING COUNT(*)>1) AND NOT EXISTS (SELECT 1 FROM song_masters WHERE id IN ('sm-upload-08c5fd9b-a07','sm-upload-0f6e0515-62c','sm-upload-5979a6ff-f6c','sm-upload-746012d3-887','sm-upload-75a8634a-1b1','sm-upload-8aa9653f-bb6','sm-upload-9ac28768-466','sm-upload-b4e17f3c-27c') AND track IS NOT NULL GROUP BY COALESCE(disc,0),track HAVING COUNT(*)>1) AND (SELECT COUNT(*) FROM storage_entries se JOIN song_instances si ON si.id=se.instance_id AND si.source_id='r2-local' AND lower(si.suffix)='wav' JOIN song_masters sm ON sm.id=si.master_id WHERE se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-75d346df2f574adeb9b44b73a2dc9fd4' AND sm.album_id!='pending-uploads')=0 AND (SELECT COUNT(*) FROM storage_entries se JOIN song_instances si ON si.id=se.instance_id AND si.source_id='r2-local' AND lower(si.suffix)='wav' JOIN song_masters sm ON sm.id=si.master_id WHERE se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-75d346df2f574adeb9b44b73a2dc9fd4' AND sm.album_id!='pending-uploads' AND sm.id NOT IN (''))=0 AND (SELECT COUNT(*) FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id JOIN storage_entries se ON se.instance_id=si.id AND se.kind='file' WHERE sm.id IN ('') AND sm.album_id IN ('') AND se.source_id='r2-local' AND se.parent_id='se-75d346df2f574adeb9b44b73a2dc9fd4' AND lower(si.suffix)='wav')=0);
